using Camber.Core;

var failures = new List<string>();
var count = 0;
void Test(string name, Action run) { count++; try { run(); Console.WriteLine($"PASS {name}"); } catch (Exception e) { failures.Add(name); Console.WriteLine($"FAIL {name}: {e.Message}"); } }
void Assert(bool value) { if (!value) throw new Exception("Assertion failed"); }
void Throws<T>(Action run) where T : Exception { try { run(); } catch (T) { return; } throw new Exception($"Expected {typeof(T).Name}"); }
SessionController Active() { var s = new SessionController(); s.Pair("phone"); s.Approve("phone"); return s; }
Test("pairing alone cannot authorize frames", () => { var s = new SessionController(); s.Pair("phone"); Assert(!s.AcceptFrame(s.Snapshot.Generation)); });
Test("only selected phone can approve", () => { var s = new SessionController(); s.Pair("phone"); Throws<UnauthorizedAccessException>(() => s.Approve("other")); });
Test("pause fences already queued frames", () => { var s = Active(); var g = s.Snapshot.Generation; Assert(s.AcceptFrame(g)); s.Pause(); Assert(!s.AcceptFrame(g)); Assert(!s.AcceptFrame(s.Snapshot.Generation)); });
Test("disconnect never overrides pause", () => { var s = Active(); s.Pause(); s.Disconnect(); Assert(s.Snapshot.Phase == SessionPhase.Paused); });
Test("stop requires new phone consent", () => { var s = Active(); s.Stop(); Throws<InvalidOperationException>(() => s.Approve("phone")); Throws<InvalidOperationException>(() => s.ResumeFromPhone("phone")); });
Test("stale configuration ack is ignored", () => { var s = Active(); var g = s.Snapshot.Generation; s.Pause(); s.ApplyAcknowledgment(new("1", true, g, new(CameraFacing.Front, VideoMode.HD, VideoMode.FullHD), null)); Assert(s.Snapshot.Configuration.Camera == CameraFacing.Back); });
Test("active phone cannot be replaced", () => { var s = Active(); Throws<InvalidOperationException>(() => s.Pair("other")); });
Test("disconnect revokes current consent immediately", () => { var s = Active(); var g = s.Snapshot.Generation; s.Disconnect(); Assert(!s.AcceptFrame(g) && s.Snapshot.PrivacyBlocked); s.Stop(); Assert(!s.AcceptFrame(g)); });
Test("idle timeout releases capture", () => { var c = new FakeClock(); var s = new SessionController(c); s.Pair("phone"); s.Approve("phone"); s.Tick(false, false); c.Advance(5); Assert(s.Tick(false, false).Phase == SessionPhase.Paused); });
Test("visible preview prevents idle pause", () => { var c = new FakeClock(); var s = new SessionController(c); s.Pair("phone"); s.Approve("phone"); s.Tick(false, true); c.Advance(10); Assert(s.Tick(false, true).Approved); });
Test("reconnect approval expires", () => { var c = new FakeClock(); var s = new SessionController(c); s.Pair("phone"); s.Approve("phone"); s.Disconnect(); c.Advance(30); Assert(!s.Tick(false, true).Approved); });
Test("pairing tokens are single-use", () => { var p = new PairingService(); var q = p.Create("pc", "PC", "https://192.168.1.2:47771", new('A', 64)); Assert(p.Consume(q.Secret, 1)); Assert(!p.Consume(q.Secret, 1)); });
Test("pairing tokens expire at two minutes", () => { var c = new FakeClock(); var p = new PairingService(c); var q = p.Create("pc", "PC", "https://192.168.1.2:47771", new('A', 64)); c.Advance(120); Assert(!p.Consume(q.Secret, 1)); });
Test("new QR invalidates old QR", () => { var p = new PairingService(); var a = p.Create("pc", "PC", "https://192.168.1.2:47771", new('A', 64)); var b = p.Create("pc", "PC", "https://192.168.1.2:47771", new('A', 64)); Assert(!p.Consume(a.Secret, 1)); Assert(p.Consume(b.Secret, 1)); });
Test("pairing brute force is rate limited", () => { var p = new PairingService(); var q = p.Create("pc", "PC", "https://192.168.1.2:47771", new('A', 64)); for (int i = 0; i < 5; i++) p.Consume(new('0', 64), 1); Assert(!p.Consume(q.Secret, 1)); });
Test("slow decoder does not cut network bitrate", () => { var a = new AdaptiveQuality(); for (int i = 0; i < 3; i++) a.Observe(new StageMetrics(20, 10, 5, 62, 0, 15, false, false)); Assert(a.Mode == VideoMode.HD && a.Bitrate == 8_000_000); });
Test("network congestion lowers bitrate", () => { var a = new AdaptiveQuality(); for (int i = 0; i < 3; i++) a.Observe(new StageMetrics(20, 10, 120, 5, .1, 25, false, false)); Assert(a.Bitrate < 8_000_000); });
Test("adaptation rejects invalid metrics", () => Throws<ArgumentException>(() => new AdaptiveQuality().Observe(new StageMetrics(double.NaN, 0, 0, 0, 0, 0, false, false))));
Test("recovery has hysteresis", () => { var a = new AdaptiveQuality(); for (int i = 0; i < 3; i++) a.Observe(new StageMetrics(20, 50, 5, 5, 0, 15, false, false)); for (int i = 0; i < 29; i++) a.Observe(new StageMetrics(20, 5, 5, 5, 0, 30, false, false)); Assert(a.Mode == VideoMode.HD); a.Observe(new StageMetrics(20, 5, 5, 5, 0, 30, false, false)); Assert(a.Mode == VideoMode.FullHD); });
Test("unsolicited acknowledgment cannot change configuration", () => { var p = new PendingCommands(); Assert(!p.Consume(new("unknown", true, 1, null, null), DateTimeOffset.UnixEpoch)); });
Test("acknowledgments are generation bound and single use", () => { var p = new PendingCommands(); var now = DateTimeOffset.UnixEpoch; p.Add("a", 3, now); Assert(p.Consume(new("a", true, 3, null, null), now)); Assert(!p.Consume(new("a", true, 3, null, null), now)); p.Add("b", 3, now); Assert(!p.Consume(new("b", true, 4, null, null), now)); });
Test("configuration requests expire", () => { var p = new PendingCommands(); var now = DateTimeOffset.UnixEpoch; p.Add("a", 1, now); Assert(!p.Consume(new("a", true, 1, null, null), now.AddSeconds(10))); });
Test("configuration requests are bounded", () => { var p = new PendingCommands(); for (int i = 0; i < 16; i++) p.Add(i.ToString(), 1, DateTimeOffset.UnixEpoch); Throws<InvalidOperationException>(() => p.Add("overflow", 1, DateTimeOffset.UnixEpoch)); });
Test("decoded mailbox keeps only newest frame", () => { var box = new LatestFrame<object>(); var latest = new object(); box.Publish(new()); box.Publish(latest); Assert(box.Overwritten == 1 && ReferenceEquals(box.Take(), latest) && box.Take() is null); });
Test("late Start cannot cross Stop boundary", () => { var s = new SessionController(); s.Pair("phone"); var old = s.Snapshot.Generation; s.Stop(); Throws<InvalidOperationException>(() => s.ApproveRequest("phone", old)); Assert(!s.Snapshot.Approved); });
Test("fresh Start can authorize a stopped session", () => { var s = new SessionController(); s.Pair("phone"); s.Stop(); var state = s.ApproveRequest("phone", s.Snapshot.Generation); Assert(state.Approved && !state.PrivacyBlocked); });
Test("reaction requires current camera consent", () => { var gate = new ReactionGate(); var s = Active(); Assert(!gate.TryTrigger(s.Snapshot, s.Snapshot.Generation - 1, ReactionKind.Hearts, true)); s.Pause(); Assert(!gate.TryTrigger(s.Snapshot, s.Snapshot.Generation, ReactionKind.Hearts, true)); });
Test("reactions are bounded and disabled means disabled", () => { var c = new FakeClock(); var gate = new ReactionGate(c); var s = Active(); Assert(!gate.TryTrigger(s.Snapshot, s.Snapshot.Generation, ReactionKind.Hearts, false)); Assert(!gate.TryTrigger(s.Snapshot, s.Snapshot.Generation, (ReactionKind)99, true)); Assert(gate.TryTrigger(s.Snapshot, s.Snapshot.Generation, ReactionKind.Hearts, true)); Assert(!gate.TryTrigger(s.Snapshot, s.Snapshot.Generation, ReactionKind.Confetti, true)); c.Advance(4); Assert(gate.TryTrigger(s.Snapshot, s.Snapshot.Generation, ReactionKind.Confetti, true)); });
Test("natural outgoing view is the default and mirroring is explicit", () => { var s = Active(); Assert(!s.Snapshot.Configuration.OutputMirror && !new VisualSettings().PreviewMirror); s.SetOutputMirror(true); Assert(s.Snapshot.Configuration.OutputMirror); s.SetOutputMirror(false); Assert(!s.Snapshot.Configuration.OutputMirror); });
Test("reaction IDs reject replay and malformed requests",()=>{var r=new ReactionRequests();var id=Guid.NewGuid().ToString("N");Assert(r.Accept(id,1));Assert(!r.Accept(id,1));Assert(!r.Accept("invalid",1));Assert(r.Accept(id,2));});
Test("reaction ID storage is bounded and fails closed",()=>{var r=new ReactionRequests();for(int i=0;i<4096;i++)Assert(r.Accept(Guid.NewGuid().ToString("N"),1));Assert(!r.Accept(Guid.NewGuid().ToString("N"),1));});
Test("reaction IDs cannot be replayed with different casing", () => { var r=new ReactionRequests();var id=Guid.NewGuid().ToString("N");Assert(r.Accept(id.ToLowerInvariant(),1));Assert(!r.Accept(id.ToUpperInvariant(),1)); });
Test("unknown telemetry cannot restore downgraded capture",()=>{var p=new AdaptiveQuality();for(int i=0;i<3;i++)p.Observe(new QualitySample(EncodeMs:50));for(int i=0;i<60;i++)p.Observe(new QualitySample());Assert(p.Mode==VideoMode.HD);});
Test("requested 720p maximum survives healthy recovery",()=>{var p=new AdaptiveQuality();p.Prefer(VideoMode.HD);for(int i=0;i<90;i++)p.Observe(new QualitySample(CaptureFps:30));Assert(p.Mode==VideoMode.HD && p.Bitrate==11_000_000);});
Test("codec limits remain within the measured envelope",()=>{var p=new AdaptiveQuality();for(int i=0;i<90;i++)p.Observe(new QualitySample(NetworkRttMs:150));Assert(p.Bitrate==2_000_000 && p.Mode==VideoMode.HD);for(int i=0;i<600;i++)p.Observe(new QualitySample(CaptureFps:30,NetworkRttMs:20,LossRatio:0));Assert(p.Bitrate==12_000_000);});
Test("two poor samples do not cause a downgrade",()=>{var p=new AdaptiveQuality();for(int i=0;i<2;i++)p.Observe(new QualitySample(EncodeMs:50));Assert(p.Mode==VideoMode.FullHD);p.Observe(new QualitySample(EncodeMs:50));Assert(p.Mode==VideoMode.HD);});
Test("invalid optional measurements are rejected",()=>{Throws<ArgumentException>(()=>new AdaptiveQuality().Observe(new QualitySample(NetworkRttMs:double.NaN)));Throws<ArgumentException>(()=>new AdaptiveQuality().Observe(new QualitySample(LossRatio:1.1)));Assert(new VisualSettings().Enhancement==EnhancementMode.Original);});
Test("settings serialize rather than overlap across both interfaces",()=>{var p=new PendingCommands();var at=DateTimeOffset.UnixEpoch;p.AddExclusive("first",1,at);Throws<InvalidOperationException>(()=>p.AddExclusive("second",1,at));Assert(p.Consume(new("first",true,1,null,null),at));p.AddExclusive("second",1,at);Assert(p.IsPending(at));Assert(!p.IsPending(at.AddSeconds(11)));});
Test("enhancement confirmation matches request ID and generation",()=>{var v=new Camber.Host.VideoControl();var session=Active();var g=session.Snapshot.Generation;v.ExpectEnhancement("new",g,EnhancementMode.Natural);var old=System.Text.Json.JsonSerializer.SerializeToElement(new {generation=g,id="old",requested=1,applied=1,reason="Applied",processingMs=1.0});Assert(!v.AppliedEnhancement(old,session.Snapshot,EnhancementMode.Natural));var current=System.Text.Json.JsonSerializer.SerializeToElement(new {generation=g,id="new",requested=1,applied=1,reason="Applied",processingMs=1.0});Assert(v.AppliedEnhancement(current,session.Snapshot,EnhancementMode.Natural));session.Pause();Assert(!v.AppliedEnhancement(current,session.Snapshot,EnhancementMode.Natural));});
Test("phone quality commands require advertised capability and consent",()=>{var v=new Camber.Host.VideoControl();var session=Active();var g=session.Snapshot.Generation;var data=System.Text.Json.JsonSerializer.SerializeToElement(new {generation=g,width=1920,height=1080,captureFps=30,maxBitrateBps=8000000,networkRttMs=150});for(int i=1;i<=3;i++)Assert(v.Observe(data,session.Snapshot,i*1000)==null);v.Capabilities(System.Text.Json.JsonSerializer.SerializeToElement(new {videoQuality=true}));Assert(v.Observe(data,session.Snapshot,4000)!=null);session.Pause();Assert(v.Observe(data,session.Snapshot,5000)==null);});
Test("malformed and excessive quality telemetry is rejected",()=>{var v=new Camber.Host.VideoControl();var session=Active();var data=System.Text.Json.JsonSerializer.SerializeToElement(new {generation=session.Snapshot.Generation,width=1920,height=1080,captureFps=30,lossRatio=2});Throws<ArgumentException>(()=>v.Observe(data,session.Snapshot,1000));});
Test("lens selected before Start is applied only with fresh consent",()=>{var session=new SessionController();session.Pair("phone");var g=session.Snapshot.Generation;var result=session.ApproveRequest("phone",g,CameraFacing.Front);Assert(result.Approved && result.Configuration.Camera==CameraFacing.Front);session.Stop();Throws<InvalidOperationException>(()=>session.ApproveRequest("phone",g,CameraFacing.Back));Assert(session.Snapshot.Configuration.Camera==CameraFacing.Front);});
Test("missing network measurements cannot imply network recovery",()=>{var p=new AdaptiveQuality();for(int i=0;i<3;i++)p.Observe(new QualitySample(NetworkRttMs:150,LossRatio:.1));var lower=p.Bitrate;for(int i=0;i<60;i++)p.Observe(new QualitySample(CaptureFps:30));Assert(p.Bitrate==lower);for(int i=0;i<30;i++)p.Observe(new QualitySample(NetworkRttMs:20,LossRatio:0));Assert(p.Bitrate>lower);});
Test("portrait capture keeps dimensions within the existing pixel budget",()=>{var v=new Camber.Host.VideoControl();var session=Active();v.Capabilities(System.Text.Json.JsonSerializer.SerializeToElement(new {videoQuality=true}));var data=System.Text.Json.JsonSerializer.SerializeToElement(new {generation=session.Snapshot.Generation,width=1080,height=1920,captureFps=30,maxBitrateBps=8000000});Assert(v.Observe(data,session.Snapshot,1000)==null);Assert(v.Actual.Width==1080 && v.Actual.Height==1920);var large=System.Text.Json.JsonSerializer.SerializeToElement(new {generation=session.Snapshot.Generation,width=1920,height=1920,captureFps=30});Throws<ArgumentException>(()=>v.Observe(large,session.Snapshot,2000));});
Test("acknowledged closest capture size does not restart capture repeatedly",()=>{var v=new Camber.Host.VideoControl();var session=Active();v.Capabilities(System.Text.Json.JsonSerializer.SerializeToElement(new {videoQuality=true}));var data=System.Text.Json.JsonSerializer.SerializeToElement(new {generation=session.Snapshot.Generation,width=1280,height=720,captureFps=30,maxBitrateBps=8000000});var request=v.Observe(data,session.Snapshot,1000)!;Assert(request!=null);v.Acknowledge(System.Text.Json.JsonSerializer.SerializeToElement(new {generation=session.Snapshot.Generation,id=request.Id,ok=true}),session.Snapshot);Assert(v.Observe(data,session.Snapshot,6000)==null);Assert(session.Snapshot.Configuration.Capture==VideoMode.FullHD);});
Test("new-session status cannot display old processing confirmation",()=>{var v=new Camber.Host.VideoControl();var session=Active();var g=session.Snapshot.Generation;v.ExpectEnhancement("a",g,EnhancementMode.Natural);v.AppliedEnhancement(System.Text.Json.JsonSerializer.SerializeToElement(new {generation=g,id="a",requested=1,applied=1,reason="Applied",processingMs=1.0}),session.Snapshot,EnhancementMode.Natural);session.Pause();session.ResumeFromPhone("phone");var status=System.Text.Json.JsonSerializer.SerializeToElement(v.StatusFor(session.Snapshot,EnhancementMode.Natural));Assert(status.GetProperty("enhancement").GetProperty("Applied").GetInt32()==0);Assert(status.GetProperty("sample").GetProperty("CaptureFps").ValueKind==System.Text.Json.JsonValueKind.Null);});
Console.WriteLine($"{count - failures.Count}/{count} passed");
return failures.Count == 0 ? 0 : 1;
sealed class FakeClock : TimeProvider { private DateTimeOffset now = DateTimeOffset.UnixEpoch; public override DateTimeOffset GetUtcNow() => now; public void Advance(int seconds) => now = now.AddSeconds(seconds); }
